-- Enrichment Batch 21 — Hong Kong government schemes + HKUST named awards (974-977), 2026-10-28.
-- Replay of the live executed statements. All four records were ADDED at reliability 10 from official
-- pages fetched 2026-10-28 (see docs/SCHOLARSHIP_ENRICHMENT_BATCH_21_2026-10-28.md).
-- Pre-checks run before writing (all clear):
--   * no existing records titled Belt and Road / HKSAR / Global Learners / Future Leaders / Outstanding Performance;
--   * none of the 4 target source URLs existed in sources (unique idx_sources_url safe);
--   * (university_id, scholarship_name) unique index: new names distinct from rows 188/461/463 at uni 217.
-- Expected counters after replay (baseline 2026-10-28): active 547, retired 178, active rel4 25,
-- future deadlines 193; max IDs scholarships 977 / sources 3111 / university_scholarships 701.

-- 1) Sources 3108-3111
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3108, 'https://www.edb.gov.hk/en/edu-system/postsecondary/local-higher-edu/publicly-funded-programmes/scholarship.html', 'HKSAR Government Scholarship Fund | Education Bureau (official)', 'edb.gov.hk', 'scholarship', now(), true, true, now()), (3109, 'https://www.studyinhongkong.edu.hk/en/hong-kong-education/scholarships.php', 'Scholarships | Study in Hong Kong (official)', 'studyinhongkong.edu.hk', 'scholarship', now(), true, true, now()), (3110, 'https://join.hkust.edu.hk/global-learners-scholarship', 'Global Learners Scholarship | HKUST Undergraduate Admissions (official)', 'join.hkust.edu.hk', 'scholarship', now(), true, true, now()), (3111, 'https://join.hkust.edu.hk/future-leaders-award', 'HKUST Future Leaders Award | HKUST Undergraduate Admissions (official)', 'join.hkust.edu.hk', 'scholarship', now(), true, true, now()) RETURNING id, url;

-- 2) 974 — Belt and Road Scholarship (Hong Kong), rel 10, upcoming, NULL/not_published, NULL HKD/year/variable
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (974, 'Belt and Road Scholarship (Hong Kong)', 'HKSAR Government (Education Bureau)', 'Hong Kong SAR', 'Full Tuition Waiver', 0, 'There is no central application and no single deadline: first apply for admission to a full-time publicly-funded programme at a participating Hong Kong institution, because the universities themselves run the Belt and Road process (handling differs by institution - some invite you to register interest or submit scholarship documents inside the admission application, then shortlist and nominate their candidates for the annual competition under the HKSAR Government Scholarship Fund). Check the scholarship pages of each university you apply to and flag your interest early in the admission cycle.', NULL, 'not_published', NULL, NULL, $j$["Bachelor's", "Master's", "PhD"]$j$, $j$["Full-time publicly-funded undergraduate programmes and full-time publicly-funded research postgraduate programmes (MPhil/PhD) at Hong Kong's eight UGC-funded universities; the HKSAR Government Scholarship Fund's participating institutions also include the Hong Kong Academy for Performing Arts and the Vocational Training Council"]$j$, $j$["First-year non-local students from Belt and Road countries - (Designated Countries) Indonesia, Malaysia, Thailand, Myanmar, Mongolia, Kazakhstan; (Other Countries) other Belt and Road countries as listed on the Belt and Road Portal; (Research Postgraduate) any Belt and Road country"]$j$, NULL, NULL, false, true, $desc$The Belt and Road Scholarship is Hong Kong's flagship government scholarship for students from Belt and Road countries, run under the Targeted Scholarship Scheme of the HKSAR Government Scholarship Fund (the Education Bureau fund established in 2008). It pays the full tuition fees of a full-time publicly-funded programme for the normal duration of study, renewed annually subject to satisfactory academic performance. The scheme began in 2016/17 for Indonesian students and grew into the Designated Countries strand - Malaysia and Thailand (2017/18), Myanmar (2019/20), Mongolia (2022/23) and Kazakhstan (2024/25) - and in 2019/20 it was expanded to cover all Belt and Road regions through two further strands: Belt and Road Scholarship (Other Countries) for first-year non-local undergraduates from any other Belt and Road country, and Belt and Road Scholarship (Research Postgraduate) for first-year research postgraduate students (MPhil/PhD) from Belt and Road countries. The reference list of Belt and Road countries is the one published on the Belt and Road Portal. Competition is real: after a further HK$1 billion injection, the annual quota rose to 150 places in 2024/25 (Designated Countries 55, Other Countries 70, Research Postgraduate 25), spread across the eight UGC-funded universities. There is no central application portal - interested students apply for admission normally and work through the institution that admits them; institutions judge candidates on the Fund's criteria (excellent academic performance, recognised contribution to the institution/society, demonstrated leadership and good communication skills, and strong commitment to the Hong Kong community). For Central Asian applicants: Kazakhstan has its own designated quota, while other Belt and Road countries of the region compete in the Other Countries strand - the official distribution annexes record awardees from Tajikistan and Kyrgyzstan in earlier years and, in 2024/25, one new undergraduate awardee from Uzbekistan (at Lingnan University), confirming that the strand is open to the country in practice as well as on paper.$desc$, $req$Be a first-year non-local student admitted to a full-time publicly-funded programme at a participating Hong Kong institution: undergraduate for the Designated Countries and Other Countries strands, research postgraduate (MPhil/PhD) for the Research Postgraduate strand. Your nationality decides your strand: Indonesia, Malaysia, Thailand, Myanmar, Mongolia and Kazakhstan have designated country schemes; nationals of other Belt and Road countries (reference list on the Belt and Road Portal) enter the Other Countries competition; the Research Postgraduate strand accepts any Belt and Road country. There is no form at the Education Bureau - the admitting institution runs the scholarship process within its own admissions/scholarship system (some ask you to indicate interest and upload supporting documents, others shortlist from admission files and nominate), applying the HKSAR Government Scholarship Fund criteria: excellent academic performance; recognised contribution to your institution or society; demonstrated leadership and good communication skills; and strong commitment to the Hong Kong community. The award then covers the full tuition fee each year and renews annually subject to your satisfactory academic performance for the programme's normal duration. English-language and GPA expectations belong to the host programme's admission requirements - the scheme publishes no single IELTS or GPA cutoff - so min_gpa/min_ielts are not recorded.$req$, 'https://www.edb.gov.hk/en/edu-system/postsecondary/local-higher-edu/publicly-funded-programmes/scholarship.html', 'https://www.edb.gov.hk/en/edu-system/postsecondary/local-higher-edu/publicly-funded-programmes/scholarship.html', 'https://www.studyinhongkong.edu.hk/en/hong-kong-education/scholarships.php', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 21) from official HKSAR Government pages fetched the same day: the Education Bureau's HKSAR Government Scholarship Fund page in full (Belt and Road Scholarship under the Targeted Scholarship Scheme since 2016/17, expanded 2019/20 into Designated Countries - Indonesia, Malaysia, Thailand, Myanmar, Mongolia, Kazakhstan - Other Countries and Research Postgraduate strands; awarded to first-year non-local students in full-time publicly-funded undergraduate or research postgraduate programmes; covers full tuition fees, tenable for the normal duration, renewed annually subject to satisfactory academic performance; 2024 injection of HK$1 billion raising the quota by 50% from 2024/25; Fund selection criteria (a)-(d); enquiries hksbr@edb.gov.hk), the Study in Hong Kong scholarships page (per-country start years; 'now covers all Belt and Road countries' with the country list referenced to the Belt and Road Portal; admitted students make enquiry to the institutions concerned), and the Education Bureau's May 2025 Legislative Council annex on the distribution of B&R places 2020/21-2024/25 (quota table: 2024/25 total 150 = designated 55 incl. Kazakhstan 10 and Mongolia 5, Other Countries 70, Research Postgraduate 25; nationality-by-institution tables include Tajikistan and Kyrgyzstan awardees and one Uzbekistan awardee at Lingnan University in 2024/25 under Other Countries). The Belt and Road Portal country-list URL returned 502 (WAF) on the fetch attempt, so country eligibility is phrased through the EDB definition plus the annex evidence rather than through the Portal list itself. Award stored as NULL (HKD, 'year', 'variable'): the scholarship equals each host programme's full tuition fee, which varies by institution and level; amount_usd_value 0 (non-USD). deadline_date NULL/'not_published' - no central deadline exists; status 'upcoming' ahead of each year's admission-driven institutional rounds. university_id NULL (ten-institution government scheme) - no university_scholarships row. degree_levels include Master's only in the research-postgraduate sense (MPhil), as the text states. Linked sources: 3108 (Education Bureau) and 3109 (Study in Hong Kong). One of the two HKSAR government schemes first documented as nomination routes inside record 36 (pass 114) and now added standalone after individual verification.$note$, NULL, NULL, 'HKD', 'year', 'variable', NULL, 'Full coverage of the programme tuition fees for the normal duration of study, renewed annually subject to satisfactory academic performance (150 places per year since 2024/25: 55 Designated Countries, 70 Other Countries, 25 Research Postgraduate)', 'The scholarship covers the full annual tuition fee of the full-time publicly-funded programme; it is a tuition-fee scholarship - no separate living allowance is part of the stated government package, so budget separately for accommodation and living costs.', 'No scholarship-level IELTS figure; English requirements sit inside each host university and programme admission requirements.', $j$["Admission application to a full-time publicly-funded undergraduate or research postgraduate programme at a participating institution - there is no central Belt and Road application form", "Whatever the admitting institution asks for in its own Belt and Road process (some universities invite interest registration and supporting documents inside the admission application; candidates are judged on academic excellence, contribution, leadership/communication skills and commitment to Hong Kong)"]$j$, NULL, NULL, $json$[{"academic_year": "2024/25", "places_total": 150, "designated_countries": 55, "other_countries": 70, "research_postgraduate": 25}, {"pattern": "Annual and admission-driven: apply for September admission at a participating institution and pursue its internal Belt and Road nomination/indication-of-interest process; awards run for the normal duration with annual renewal on satisfactory performance"}]$json$) RETURNING id, title, source_reliability;

-- 3) 975 — HKSAR Government Scholarship (Outstanding Performance), rel 10, upcoming, NULL/not_published
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (975, 'HKSAR Government Scholarship (Outstanding Performance)', 'HKSAR Government (Education Bureau)', 'Hong Kong SAR', 'Annual Grant', 0, 'No central application or deadline exists: each year the Government distributes the Fund money to the ten participating institutions, and the institutions themselves decide the awards for their own outstanding students (some run in-year application windows - often from around September - others select and nominate). Apply for admission to a full-time publicly-funded programme first, then follow your institution''s scholarship announcements; first-year non-local students are among those the universities put forward.', NULL, 'not_published', NULL, NULL, $j$["Bachelor's", "Master's", "PhD"]$j$, $j$["Full-time publicly-funded programmes at degree or above level at the Fund's ten institutions: the eight UGC-funded universities, the Hong Kong Academy for Performing Arts and the Vocational Training Council (a sub-degree strand also exists, paying HK$20,000-HK$30,000 per year)"]$j$, $j$["Outstanding local and non-local students enrolled full-time in publicly-funded programmes at the ten participating institutions"]$j$, NULL, NULL, false, true, $desc$The HKSAR Government Scholarship - formally the Scholarships for Outstanding Performance (SOP) under the HKSAR Government Scholarship Fund - is the Hong Kong government's core merit scholarship for students already admitted to the city's publicly-funded institutions. The Fund was established in 2008 with HK$1 billion to attract outstanding local students to study at home and meritorious non-local students to choose Hong Kong; its investment income is distributed annually to the ten participating institutions (the eight UGC-funded universities, the Hong Kong Academy for Performing Arts and the Vocational Training Council), and the institutions decide who is awarded. At degree-or-above level the scholarship pays HK$80,000 per year to non-local students (HK$40,000 to local students), is tenable for the normal duration of the programme and renews annually subject to satisfactory academic performance; a sub-degree strand added in 2011/12 pays HK$20,000-HK$30,000 per year to local and non-local students alike. It is a sizeable, real channel: in 2024/25 it reached 826 degree-or-above students with about HK$47 million, plus 549 sub-degree students. Institutions judge candidates not on grades alone but on the Fund's published criteria - excellent academic performance, recognised contribution to the institution/society, demonstrated leadership and good communication skills, and strong commitment to the Hong Kong community. The same Fund also carries smaller sibling awards that institutions administer alongside: the Talent Development Scholarship and the Reaching Out Award (HK$10,000 each - for talents in sports, music and performing arts, culture/arts/design or innovation and technology, and for institution-endorsed learning/internship/service activities outside Hong Kong respectively) and the Endeavour Merit Award (HK$15,000 for post-secondary students with special educational needs); its Belt and Road strand is recorded separately (record 974).$desc$, $req$Be enrolled (or entering) full-time in a publicly-funded programme at one of the ten participating institutions - degree or above level for the HK$80,000 non-local rate, sub-degree for the HK$20,000-HK$30,000 strand. There is nothing to file with the Education Bureau: the money is distributed to the institutions and 'in deciding if a student should be awarded, the institutions take the following qualities into consideration' - excellent performance in academic studies; recognised contribution to the institution/society; demonstrated leadership and good communication skills; and/or strong commitment to the Hong Kong community (with the equivalent list for sub-degree students). Each institution runs its own selection timetable and instructions, so watch its scholarship pages after admission; universities commonly put forward outstanding first-year students. Once awarded at degree-or-above level, the scholarship runs for the normal duration of the programme and is renewed annually subject to satisfactory academic performance - treat continued strong performance as a condition, not a formality. No single GPA cutoff and no scholarship-level IELTS figure are published at scheme level (selection is comparative inside each institution and language requirements belong to programme admission), so min_gpa/min_ielts are not recorded.$req$, 'https://www.edb.gov.hk/en/edu-system/postsecondary/local-higher-edu/publicly-funded-programmes/scholarship.html', 'https://www.edb.gov.hk/en/edu-system/postsecondary/local-higher-edu/publicly-funded-programmes/scholarship.html', 'https://www.edb.gov.hk/en/edu-system/postsecondary/local-higher-edu/publicly-funded-programmes/scholarship.html', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 21) from the Education Bureau's HKSAR Government Scholarship Fund page fetched the same day and read in full (chunks 0-1 plus the institutional links section): Fund established 2008 with HK$1 billion for outstanding students in full-time publicly-funded programmes at degree or above level, investment income distributed annually to the ten institutions (eight UGC-funded institutions, HKAPA, VTC); Scholarships for Outstanding Performance established 2008 - HK$40,000 per year for local students and HK$80,000 per year for non-local students at degree-or-above level, tenable for the normal duration and renewed annually subject to satisfactory academic performance; 2011 injection of HK$250 million extended the benefit to full-time publicly-funded sub-degree programmes from 2011/12 at HK$20,000-HK$30,000 per year for both local and non-local students (five institutions originally; CityU and PolyU ceased full-time publicly-funded sub-degree programmes from 2022/23); awardee tables (2024/25: 826 degree-or-above awardees, HK$47 million; 549 sub-degree awardees, HK$11 million); institutions decide awards using the published criteria (academic excellence, recognised contribution, leadership and communication skills, commitment to the Hong Kong community); sibling awards under the Fund - Talent Development Scholarship and Reaching Out Award at HK$10,000 each (2012/13, after a HK$1 billion injection; talent areas sports and games, music and performing arts, culture arts and design, innovation science and technology) and Endeavour Merit Award at HK$15,000 for students with special educational needs (2013/14). The Study in Hong Kong scholarships page fetched the same day confirms the non-local framing (HK$80,000, approximately US$10,300, per year). Title uses the institution-facing name 'HKSAR Government Scholarship' (as listed for example on the CUHK admission-scholarships page, record 36) with the formal SOP name appended. Award stored as NULL (HKD, 'year', 'variable') because the scheme has several published rates (80,000/40,000 at degree-or-above by residency, 20,000-30,000 sub-degree); amount_usd_value 0 (non-USD). deadline_date NULL/'not_published'; status 'upcoming' (annual institution-run selection). degree_levels include Master's and PhD because the official scope is 'degree or above level' publicly-funded programmes. university_id NULL (ten-institution scheme), no university_scholarships row. Linked source: 3108 (Education Bureau). The second of the two HKSAR government schemes first documented as nomination routes inside record 36 (pass 114) and now added standalone after individual verification; the Belt and Road strand of the same Fund is record 974.$note$, NULL, NULL, 'HKD', 'year', 'variable', NULL, 'HK$80,000 per year for non-local students at degree-or-above level (HK$40,000 for local students), tenable for the normal duration and renewed annually on satisfactory performance; sub-degree strand HK$20,000-HK$30,000 per year', 'A cash scholarship towards the costs of study rather than a fee waiver: for non-locals HK$80,000 per year offsets a substantial share of the non-local tuition fee and living costs but does not cover the full fee on its own.', 'No scholarship-level IELTS figure; English requirements belong to each institution and programme admission.', $j$["No Education Bureau form exists - admission to a full-time publicly-funded programme at one of the ten participating institutions is the entry ticket", "Follow your institution's own scholarship selection or application announcements after admission (institutions judge academic excellence, contribution, leadership/communication and commitment to Hong Kong)"]$j$, NULL, NULL, $json$[{"pattern": "Annual: the Government distributes Fund income to the ten institutions each academic year and each institution selects its awardees (often from around September); awards at degree-or-above level renew yearly on satisfactory performance for the normal programme duration"}]$json$) RETURNING id, title, source_reliability;

-- 4) 976 — HKUST Global Learners Scholarship, rel 10, open, NULL/not_published, uni 217
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (976, 'HKUST Global Learners Scholarship', 'Hong Kong University of Science and Technology', 'Hong Kong SAR', 'Full Tuition Waiver', 0, 'No scholarship application and no scholarship deadline: all undergraduate applicants from underrepresented nationalities are automatically considered, and the decision is normally notified together with the admission offer. The only deadlines are the admission ones - for 2027/28 entry the HKUST online application is open (opened 2 October 2026); the Priority Round closes 25 November 2026 (offers from late December 2026) and rolling applications continue until 30 June 2027 - applying by the Priority Round is the way to hear earliest.', NULL, 'not_published', NULL, NULL, $j$["Bachelor's"]$j$, $j$["All undergraduate programmes at HKUST"]$j$, $j$["Undergraduate applicants from underrepresented nationalities (determined by the university in support of its student-diversity objective; no published country list)"]$j$, NULL, NULL, false, true, $desc$The Global Learners Scholarship is HKUST's diversity-driven entrance award: it was established to support the university's strategic objective of enhancing the diversity of the student community, and it works entirely through the admissions process. Students do not apply for it - all undergraduate programme applicants from underrepresented nationalities are automatically considered, and they are normally notified of the scholarship decision when they receive their offer of admission. A successful awardee receives a full tuition waiver, renewable for the normal duration of study subject to satisfactory academic performance; set against the non-local tuition level (HK$260,000 per year in 2027/28) this removes the single largest cost of an HKUST degree without any separate essay, form or interview stage for the scholarship itself. A school or programme office may add a top-up scholarship on top, provided the university-wide ceiling of 'full tuition fee + HK$65,000 allowance' per year is not exceeded - the same ceiling that governs HKUST's other admissions scholarships (record 51) and its need-based Future Leaders Award (record 977). The university does not publish which nationalities count as underrepresented in a given year, so the practical instruction is simply to apply for admission as early as possible and let the automatic consideration happen; the award is distinct from the financial-aid schemes run by the Scholarship and Financial Aid Office for students in financial difficulty.$desc$, $req$Apply for undergraduate admission to HKUST as a non-local applicant - that is the whole requirement for consideration: the scholarship has no application of its own, and every applicant from an underrepresented nationality is assessed automatically, with the outcome normally delivered alongside the admission offer. Which nationalities qualify as underrepresented is decided by the university under its diversity objective and is not published as a list, so there is nothing to self-certify and no separate eligibility form. Keeping the award is the active part: the full waiver renews for the normal duration of study only while academic performance remains satisfactory, and any school top-up is capped with the waiver at full tuition fee plus HK$65,000 allowance per year. Timing still matters because scholarship decisions ride on admission offers: for 2027/28 the application system opened on 2 October 2026, the Priority Round deadline is 25 November 2026 with offers from late December 2026, and rolling applications close on 30 June 2027 (see record 51 for the full admissions-scholarship family). No GPA or IELTS figure is attached to this award - both sit inside programme admission - so min_gpa/min_ielts are not recorded.$req$, 'https://join.hkust.edu.hk/global-learners-scholarship', 'https://join.hkust.edu.hk/global-learners-scholarship', 'https://join.hkust.edu.hk/global-learners-scholarship', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 21) from HKUST Undergraduate Admissions' Global Learners Scholarship page, fetched in pass 114 and re-fetched unchanged on 2026-10-28: established to support the university's objective of enhancing student diversity; no application - all undergraduate programme applicants from underrepresented nationalities are automatically considered; decision normally notified with the offer of admission; successful awardees receive a full tuition waiver renewable for the normal duration of study subject to satisfactory academic performance; school/programme top-ups allowed provided the maximum limit of 'Full Tuition Fee + HK$65,000 allowance' per year is not exceeded; financial aid via the Scholarship and Financial Aid Office is a separate route. The 2027/28 admission timeline in the deadline text and rounds JSON (system opened 2 October 2026, Priority Round 25 November 2026, rolling until 30 June 2027, non-local tuition HK$260,000 per year) comes from the HKUST pages fetched first-hand in pass 114 and recorded on record 51. Previously documented as a named sibling inside record 51 (pass 114); now a standalone record after individual verification. Award stored as NULL (HKD, 'year', 'variable') - the waiver equals the tuition fee of the year rather than a fixed sum; amount_usd_value 0. deadline_date NULL/'not_published' because the award itself has no deadline (automatic consideration throughout the admission cycle); status 'open' because 2027/28 applications opened on 2 October 2026. min_gpa/min_ielts NULL. university_id 217 (The Hong Kong University of Science and Technology); university_scholarships row 700 created. Linked source: 3110. Note for a future cleanup pass: record 592 'HKUST Admissions Scholarships (international qualifications)' (reliability 8) overlaps the family territory of record 51 and should be deduplicated against it - this award and record 977 are distinct named schemes, not duplicates of 592.$note$, 217, NULL, 'HKD', 'year', 'variable', NULL, 'Full tuition waiver, renewable for the normal duration of study subject to satisfactory academic performance; automatic consideration (no application); possible school top-up within the full tuition + HK$65,000 per year ceiling', 'The full non-local tuition fee (HK$260,000 per year in 2027/28) is waived for the normal duration of the degree, renewable on satisfactory performance; living costs are not covered by the waiver itself (a school top-up up to the HK$65,000 allowance ceiling may be added).', 'No scholarship-level IELTS figure; English requirements sit inside undergraduate admission and vary by qualification.', $j$["HKUST online undergraduate admission application - Global Learners consideration is automatic for applicants from underrepresented nationalities; no scholarship form, essay or documents of its own"]$j$, NULL, NULL, $json$[{"round": "2027/28 entry - Priority Round", "opens": "2026-10-02", "deadline": "2026-11-25", "offers_from": "2026-12", "status": "open"}, {"round": "2027/28 entry - rolling", "from": "2026-11-26", "closes": "2027-06-30", "status": "open"}, {"pattern": "Annual and fully automatic inside the admission cycle; scholarship decisions are notified with admission offers"}]$json$) RETURNING id, title, source_reliability;

-- 5) 977 — HKUST Future Leaders Award, rel 10, open, 2026-12-02/fixed, uni 217
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (977, 'HKUST Future Leaders Award', 'Hong Kong University of Science and Technology', 'Hong Kong SAR', 'Tuition Waiver', 0, 'Two deadlines in the 2027/28 cycle: (1) submit the HKUST undergraduate admission application by the early (Priority Round) deadline, 25 November 2026 - only applicants recommended for admission in the Priority Round are eligible - and (2) submit the Future Leaders Award application by 2 December 2026. Results are announced from late December 2026 to early January 2027, with acceptance of the admission offer and the Award due by the end of January 2027.', '2026-12-02', 'fixed', NULL, NULL, $j$["Bachelor's"]$j$, $j$["All undergraduate programmes at HKUST (direct-from-high-school entrants only)"]$j$, $j$["Non-local undergraduate applicants admitted directly from high school who can demonstrate and document exceptional financial need (post-secondary applicants are not eligible)"]$j$, NULL, NULL, true, true, $desc$The Future Leaders Award is HKUST's distinguished need-based scholarship for exceptional non-local students who demonstrate academic excellence alongside genuine financial need - it exists, in the university's words, to give such students access to higher-quality education. It targets a specific profile: non-local applicants who have shown resilience in overcoming challenges on their journey to university and who have the potential to contribute positively to the HKUST community, admitted directly from high school (post-secondary applicants are not eligible) and recommended for admission in the Priority Round. The support is scaled to the student's level of financial need and can rise to full tuition plus a living allowance, renewable for applicants with exceptional financial need; as with all HKUST admissions scholarships, other top-up offers may be added only up to the ceiling of 'full tuition fee + HK$65,000 allowance' per year. Financial need is not self-declared lightly - applicants must demonstrate and provide proof of exceptional financial need, and the application file (a Statement of Circumstance describing the family's financial situation, intended contribution to HKUST and the impact of the award, a Declaration on Family Finances, and a reference letter) is due by 2 December 2026 for 2027/28 entry, a week after the Priority Round admission deadline of 25 November 2026. Results land from late December 2026 to early January 2027, so a successful applicant can weigh the complete package before confirming acceptance of the admission offer and the Award by the end of January 2027 - making this the one HKUST channel where a well-prepared financial file, not grades alone, unlocks what can amount to a full-ride package (see also the automatic merit channel, record 51, and the nationality-based Global Learners waiver, record 976).$desc$, $req$Meet all of these conditions: be a non-local applicant; be admitted to HKUST directly from high school (post-secondary applicants are not eligible); meet HKUST's admission requirements and be recommended for admission in the Priority Round; and demonstrate - with proof - exceptional financial need, alongside the resilience and community-contribution qualities the award recognises. Two submissions are required in the 2027/28 cycle: the undergraduate admission application by the early (Priority Round) deadline of 25 November 2026, and the Future Leaders Award application by 2 December 2026 with three supporting documents - a Statement of Circumstance (family financial situation, your interest in joining and contributing to the HKUST community, and the positive impact receiving the scholarship would have), a Declaration on Family Finances, and a reference/recommendation letter. Results are announced from late December 2026 to early January 2027, and the page's timeline puts the deadline for accepting both the admission offer and the Award at the end of January 2027. The value is set by assessed need: support ranges up to full tuition plus a living allowance, renewable in exceptional-need cases, and any top-up offers stop at the full tuition fee + HK$65,000 annual ceiling. No numeric GPA or IELTS threshold is published for the Award itself (academic excellence is judged within admission), so min_gpa/min_ielts are not recorded.$req$, 'https://join.hkust.edu.hk/future-leaders-award', 'https://join.hkust.edu.hk/future-leaders-award', 'https://ust.az1.qualtrics.com/jfe/form/SV_7aILlwfKqVC2XoW', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 21) from HKUST Undergraduate Admissions' Future Leaders Award page, fetched in pass 114 and re-fetched on 2026-10-28: a distinguished scholarship recognising exceptional non-local students with financial need who demonstrate academic excellence; eligibility - non-local applicants who have demonstrated resilience in overcoming challenges and the potential to contribute positively to the HKUST community, must demonstrate and provide proof of exceptional financial need, must meet admission requirements and be recommended for admissions in the Priority Round, and must be admitted directly from high school (post-secondary applicants not eligible); award - support based on the level of financial need, up to full tuition plus a living allowance, renewable for applicants with exceptional financial need, with top-ups capped at 'Full Tuition Fee + HK$65,000 allowance' per year; procedures - admission application by the early-round deadline and award application by 2 December 2026 with a Statement of Circumstance, a Declaration on Family Finances and a reference/recommendation letter; results late December 2026 to early January 2027 (procedures text says acceptance can be confirmed by early January 2027; the page's timeline module labels end of January 2027 as the acceptance deadline - both are reported); application via the page's Apply link (Qualtrics form, stored as application_url). An older search-indexed version of the page additionally showed a one-off HK$50,000 tier and a HK$60,000 ceiling - neither appears on the page as fetched, so neither is recorded (as already noted in pass 114). Previously documented as a named sibling inside record 51; now standalone after individual verification. Award stored as NULL (HKD, 'year', 'variable') - need-scaled up to full tuition plus living allowance; amount_usd_value 0. deadline_date 2026-12-02 ('fixed') is the award-application deadline read on the page; status 'open' (2027/28 admission system opened 2 October 2026). financial_need_based and merit_based both true (need-tested and academic excellence required). min_gpa/min_ielts NULL. university_id 217 (The Hong Kong University of Science and Technology); university_scholarships row 701 created. Linked source: 3111.$note$, 217, NULL, 'HKD', 'year', 'variable', NULL, 'Need-based support scaled to documented financial need: up to full tuition plus a living allowance, renewable for applicants with exceptional financial need (total with top-ups capped at full tuition + HK$65,000 per year)', 'At the top of the scale the full tuition fee (HK$260,000 per year for non-locals in 2027/28) plus a living allowance is covered; the actual package follows the assessed level of financial need.', 'No scholarship-level IELTS figure; English requirements sit inside undergraduate admission and vary by qualification.', $j$["HKUST undergraduate admission application by the Priority Round deadline (25 November 2026)", "Future Leaders Award application by 2 December 2026", "Statement of Circumstance (family financial situation; interest in joining and contributing to the HKUST community; positive impact of receiving the scholarship)", "Declaration on Family Finances", "Reference Letter / Recommendation Letter"]$j$, NULL, NULL, $json$[{"round": "2027/28 entry", "admission_deadline_priority_round": "2026-11-25", "award_application_deadline": "2026-12-02", "results": "2026-12 to 2027-01", "acceptance_deadline": "2027-01 (end of January per page timeline)", "status": "open"}, {"pattern": "Annual, tied to the Priority Round: admission application by the late-November early deadline, award application in early December, results around the new year"}]$json$) RETURNING id, title, source_reliability;

-- 6) Links (974 is anchored to both government pages)
INSERT INTO scholarship_sources (scholarship_id, source_id) VALUES (974, 3108), (974, 3109), (975, 3108), (976, 3110), (977, 3111) RETURNING scholarship_id, source_id;

-- 7) university_scholarships rows for the two HKUST records (uni 217)
INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at) VALUES (700, 217, 976, 'HKUST Global Learners Scholarship', 'international_students', 'Full tuition waiver, automatic (no application), renewable for the normal duration subject to satisfactory academic performance', 'Full tuition fee waived for the normal duration (non-local tuition HK$260,000/yr in 2027/28); school top-ups possible within the full tuition + HK$65,000/yr ceiling', true, false, 'Nationality diversity: applicants from underrepresented nationalities are considered automatically; decision notified with the admission offer', 'All undergraduate applicants from underrepresented nationalities (determined by the university, no published list); no separate scholarship application; renewal on satisfactory academic performance', 'https://join.hkust.edu.hk/global-learners-scholarship', 'https://join.hkust.edu.hk/global-learners-scholarship', 'verified', now()), (701, 217, 977, 'HKUST Future Leaders Award', 'international_students', 'Need-based award: support scaled to documented financial need, up to full tuition plus living allowance, renewable for exceptional-need cases (cap incl. top-ups: full tuition + HK$65,000/yr)', 'Up to full tuition + living allowance, renewable (exceptional financial need)', true, true, 'Documented exceptional financial need, resilience, academic excellence and potential contribution to the HKUST community (Statement of Circumstance, Declaration on Family Finances, reference letter)', 'Non-local applicants admitted directly from high school and recommended for admission in the Priority Round (post-secondary applicants ineligible); admission application by 25 Nov 2026 and award application by 2 Dec 2026', 'https://join.hkust.edu.hk/future-leaders-award', 'https://join.hkust.edu.hk/future-leaders-award', 'verified', now()) RETURNING id, scholarship_id;

-- 8) Sequences
SELECT setval('scholarships_id_seq', GREATEST((SELECT MAX(id) FROM scholarships), 977), true) AS scholarships_seq, setval('sources_id_seq', GREATEST((SELECT MAX(id) FROM sources), 3111), true) AS sources_seq, setval('university_scholarships_id_seq', GREATEST((SELECT MAX(id) FROM university_scholarships), 701), true) AS us_seq;

